<section class="admin-panel" x-show="record"><h2>رسانه‌های آلبوم</h2><div class="album-add"><select x-model="albumChoice" aria-label="انتخاب تصویر از کتابخانه"><option value="">انتخاب از کتابخانه</option><template x-for="entry in (references.media||[]).filter(m=>String(m.mime_type).startsWith('image/'))" :key="entry.id"><option :value="String(entry.id)" x-text="entry.alt||entry.original_name"></option></template></select><button type="button" class="secondary-button" @click="addAlbumChoice()" :disabled="!albumChoice"><x-icon name="plus" size="16" />افزودن به آلبوم</button><label class="upload-button"><x-icon name="upload" size="17" />بارگذاری تصویر<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploads>0" @change="uploadAlbum($event)"></label></div><div class="album-editor-list"><template x-for="(entry,index) in albumItems" :key="entry.key"><div class="album-editor-row"><img :src="mediaUrl(entry.media)" alt=""><label>شرح تصویر<input x-model="entry.caption" maxlength="250"></label><label>شرح تصویر · انگلیسی<input x-model="entry.caption_en" maxlength="250" dir="ltr"></label><div><button type="button" aria-label="انتقال به بالا" @click="moveAlbum(index,-1)" :disabled="index===0"><x-icon name="arrow-up" size="16" /></button><button type="button" aria-label="انتقال به پایین" @click="moveAlbum(index,1)" :disabled="index===albumItems.length-1"><x-icon name="arrow-down" size="16" /></button><button type="button" class="danger-link" aria-label="حذف از آلبوم" @click="albumItems.splice(index,1)"><x-icon name="trash2" size="16" /></button></div></div></template></div><button type="button" class="primary-button" @click="saveAlbum()" :disabled="uploads>0">ذخیره رسانه‌های آلبوم</button></section>
